from pathlib import Path
import json
root=Path(__file__).resolve().parents[1]
rows=json.loads((root/'tools/head-profiles.json').read_text())
lines=['// AD 1.80 standing-pose regions; hitmodel_rest follows animated mesh hits.',
       '// Generated by tools/make_head_profiles.py; model coordinates, not collision-box heights.',
       'vector advr_head_lo,advr_head_hi;', 'float(entity e) ADVR_HeadProfile = {', '    local string m; m=e.model;']
for row in rows:
    lo=' '.join(str(x) for x in row['lo']);hi=' '.join(str(x) for x in row['hi'])
    lines.append(f"    if(m==\"{row['model']}\"){{advr_head_lo='{lo}';advr_head_hi='{hi}';return 1;}}")
lines+=['    return 0;','};']
(root/'game/advr_heads.qc').write_text('\n'.join(lines)+'\n')
